# W(3,3) = 27 means: for any 3-coloring of {1, ..., 27}, there exists a monochromatic AP of length 3.
# Equivalently, no valid 3-coloring of {1, ..., 27} exists without a monochromatic AP-3.
# Since 38 >= 27, coloring {1, ..., 38} is even harder - it's also impossible.

# Let me verify W(3,3) = 27 by trying to find a valid coloring of 1..26 and showing 1..27 is impossible.

def has_mono_ap3(coloring):
    n = len(coloring)
    for a in range(n):
        for d in range(1, n):
            if a + 2*d < n:
                if coloring[a] == coloring[a+d] == coloring[a+2*d]:
                    return True
    return False

# Try to find a valid 3-coloring of 1..38 using backtracking
def solve(n, num_colors):
    coloring = [-1] * n

    def is_valid(pos):
        c = coloring[pos]
        # Check all APs ending at pos
        for d in range(1, pos+1):
            a = pos - 2*d
            if a < 0:
                break
            if coloring[a] == c and coloring[a+d] == c:
                return False
        return True

    def backtrack(pos):
        if pos == n:
            return True
        for c in range(num_colors):
            coloring[pos] = c
            if is_valid(pos):
                if backtrack(pos + 1):
                    return True
        coloring[pos] = -1
        return False

    if backtrack(0):
        return coloring
    return None

